@Test("KH matrix sample z-scores match standalone base-R scale on both axes")
func khMatrixSampleZScoreROracle() throws {
    // Independently generated by Tests/Oracles/R/kh_matrix_preparation.R using base::scale.
    let input: [[Double]] = [[1, 2, 5, 9], [2, 4, 4, 8], [3, 8, 0, 7]]
    let rows = [
        -0.90429084673232818, -0.62604750927622721, 0.20868250309207573, 1.3216558529164797,
        -0.99339926779878285, -0.19867985355975659, -0.19867985355975659, 1.390758974918296,
        -0.40575133560034454, 0.94675311640080395, -1.2172540068010336, 0.67625222600057422,
    ]
    let columns = [
        -1.0, -0.87287156094396967, 0.7559289460184544, 1, 0, -0.2182178902359925,
        0.3779644730092272, 0, 1, 1.0910894511799618, -1.1338934190276817, -1,
    ]
    for (axis, reference) in [(GlifiKHMatrixAxis.rows, rows), (.columns, columns)] {
        let actual = try GlifiKHMatrixPreparation.sampleZScores(input, axis: axis)
        khMatrixExpectClose(actual.flatMap { $0 }, reference)
    }
    let perThousand = try GlifiKHMatrixPreparation.perThousand(input, exposures: [100, 200, 50])
    khMatrixExpectClose(
        perThousand.flatMap { $0 }, [10, 20, 50, 90, 10, 20, 20, 40, 60, 160, 0, 140])
}

@Test("KH matrix standardization has sample unit variance and explicit constant policy")
func khMatrixSampleZScoreProperties() throws {
    for seed in 1...64 {
        let values = (0..<13).map { sin(Double(($0 + 1) * seed)) * 7 + Double($0) }
        let result = try GlifiKHMatrixPreparation.sampleZScores([values], axis: .rows)[0]
        #expect(abs(result.reduce(0, +)) < 1e-12)
        #expect(abs(result.reduce(0) { $0 + $1 * $1 } - 12) < 1e-11)
        let changed = try GlifiKHMatrixPreparation.sampleZScores(
            [values.map { $0 * 1_024 + 16_384 }], axis: .rows)[0]
        khMatrixExpectClose(result, changed, tolerance: 1e-12)
    }
    #expect(throws: GlifiFailure.self) {
        try GlifiKHMatrixPreparation.sampleZScores([[5, 5]], axis: .rows)
    }
    #expect(
        try GlifiKHMatrixPreparation.sampleZScores([[5, 5]], axis: .rows, constantPolicy: .zeros)
            == [[0, 0]])
    #expect(
        try GlifiKHMatrixPreparation.sampleZScores(
            [[1, 5], [2, 5], [3, 5]], axis: .columns, constantPolicy: .zeros)
            == [[-1, 0], [0, 0], [1, 0]])
    #expect(throws: GlifiFailure.self) {
        try GlifiKHMatrixPreparation.sampleZScores([[1]], axis: .rows, constantPolicy: .zeros)
    }
}

@Test("KH matrix z-scores retain large offsets, subnormals and overflowing differences")
func khMatrixSampleZScoreExtremes() throws {
    let tiny = Double.leastNonzeroMagnitude
    let large = 1e308
    for values in [[0, tiny], [-large, large], [large, large.nextUp]] {
        let result = try GlifiKHMatrixPreparation.sampleZScores([values], axis: .rows)[0]
        khMatrixExpectClose(result, [-1 / sqrt(2), 1 / sqrt(2)])
    }
    let base = 1e300
    let result = try GlifiKHMatrixPreparation.sampleZScores(
        [[base, base.nextUp, base.nextUp.nextUp]], axis: .rows)
    khMatrixExpectClose(result[0], [-1, 0, 1])
    #expect(
        try GlifiKHMatrixPreparation.sampleZScores(
            [[tiny, tiny]], axis: .rows, constantPolicy: .zeros) == [[0, 0]])
}

@Test("KH matrix external exposures remain independent of filtered vocabulary")
func khMatrixExternalExposure() throws {
    #expect(
        try GlifiKHMatrixPreparation.perThousand([[2, 3], [1, 0]], exposures: [100, 2])
            == [[20, 30], [500, 0]])
    #expect(
        try GlifiKHMatrixPreparation.perThousand(
            [[0, 0]], exposures: [0], zeroExposurePolicy: .zeros)
            == [[0, 0]])
    #expect(throws: GlifiFailure.self) {
        try GlifiKHMatrixPreparation.perThousand([[0]], exposures: [0])
    }
    #expect(throws: GlifiFailure.self) {
        try GlifiKHMatrixPreparation.perThousand([[1]], exposures: [0], zeroExposurePolicy: .zeros)
    }
    let tiny = Double.leastNonzeroMagnitude
    #expect(try GlifiKHMatrixPreparation.perThousand([[tiny]], exposures: [1_000]) == [[tiny]])
    #expect(try GlifiKHMatrixPreparation.perThousand([[1e308]], exposures: [1e308]) == [[1_000]])
    for (count, exposure) in [(1e308, tiny), (tiny, 1e308)] {
        #expect(throws: GlifiFailure.self) {
            try GlifiKHMatrixPreparation.perThousand([[count]], exposures: [exposure])
        }
    }
}

@Test("KH word-context vectors match independent conditional means and preserve identities")
func khMatrixContextConditionalOracle() throws {
    let result = try GlifiKHMatrixPreparation.wordContext(
        khMatrixContextFixture(), targetIDs: ["z", "é", "absent"], contextIDs: ["right", "left"])
    #expect(result.values == [[6, 45], [10.25, 65], [0, 0]])
    #expect(result.supportCounts == [[2, 2, 0], [1, 2, 0]])
    #expect(result.targetIDs == ["z", "é", "absent"])
    #expect(result.contextIDs == ["right", "left"])
    #expect(result.levelWeights.map(\.level) == [.sentence, .paragraph])
    #expect(result.levelWeights.map(\.alpha) == [2, 0.5])
    #expect(
        try JSONDecoder().decode(GlifiKHWordContextResult.self, from: JSONEncoder().encode(result))
            == result)
    // A repeated target selects its unit once; a TF-weighted mean would yield a different result.
    let permuted = khMatrixContextFixture().map {
        GlifiKHContextCounts(
            level: $0.level, alpha: $0.alpha,
            targetCounts: $0.targetCounts.reversed().map { Array($0.reversed()) },
            contextCounts: $0.contextCounts.reversed().map { Array($0.reversed()) })
    }
    let changed = try GlifiKHMatrixPreparation.wordContext(
        permuted, targetIDs: ["absent", "é", "z"], contextIDs: ["left", "right"])
    #expect(changed.values == result.values.reversed().map { Array($0.reversed()) })
    #expect(changed.supportCounts == result.supportCounts.map { Array($0.reversed()) })
}

@Test("KH word-context levels, finite weights and conditional scales are explicit")
func khMatrixContextExtremes() throws {
    let maximum = Double.greatestFiniteMagnitude
    let tiny = Double.leastNonzeroMagnitude
    let level = GlifiKHContextCounts(
        level: .h1, targetCounts: [[1, 0], [7, 0]], contextCounts: [[maximum], [maximum]])
    let result = try GlifiKHMatrixPreparation.wordContext(
        [level], targetIDs: ["present", "absent"], contextIDs: ["context"])
    #expect(result.values == [[maximum], [0]])
    let conditionalScale = GlifiKHContextCounts(
        level: .h2, targetCounts: [[1], [0]], contextCounts: [[tiny], [maximum]])
    #expect(
        try GlifiKHMatrixPreparation.wordContext(
            [conditionalScale], targetIDs: ["t"], contextIDs: ["c"]
        ).values == [[tiny]])
    let weights = [
        GlifiKHContextCounts(level: .sentence, alpha: 2, targetCounts: [[1]], contextCounts: [[3]]),
        GlifiKHContextCounts(
            level: .paragraph, alpha: -0.5, targetCounts: [[1]], contextCounts: [[3]]),
    ]
    #expect(
        try GlifiKHMatrixPreparation.wordContext(
            weights, targetIDs: ["t"], contextIDs: ["c"]
        ).values == [[4.5]])
    let overflowing = GlifiKHContextCounts(
        level: .h1, alpha: 2, targetCounts: [[1]], contextCounts: [[maximum]])
    #expect(throws: GlifiFailure.self) {
        try GlifiKHMatrixPreparation.wordContext([overflowing], targetIDs: ["t"], contextIDs: ["c"])
    }
}

@Test("KH CA coordinates match base-R SVD norms and all nine scaling combinations reconstruct P")
func khMatrixCorrespondenceScalingOracle() throws {
    let simple = try GlifiMultivariateMethods.correspondenceAnalysis([[30, 10], [10, 30]])
    for (scaling, expected) in [
        (GlifiKHCorrespondenceScaling.principal, 0.25), (.standard, 1), (.symmetric, 0.5),
    ] {
        let projected = try GlifiKHMatrixPreparation.correspondenceCoordinates(
            simple, rowScaling: scaling, columnScaling: scaling)
        let rowNorm = zip(projected.rowMasses, projected.rowCoordinates).reduce(0) {
            $0 + $1.0 * $1.1[0] * $1.1[0]
        }
        let columnNorm = zip(projected.columnMasses, projected.columnCoordinates).reduce(0) {
            $0 + $1.0 * $1.1[0] * $1.1[0]
        }
        #expect(abs(rowNorm - expected) < 1e-12)
        #expect(abs(columnNorm - expected) < 1e-12)
    }
    let matrix: [[Double]] = [[10, 2, 0, 0], [0, 0, 0, 0], [2, 8, 3, 0], [1, 1, 9, 0]]
    let ca = try GlifiMultivariateMethods.correspondenceAnalysis(matrix)
    let total = matrix.flatMap { $0 }.reduce(0, +)
    let modes: [(GlifiKHCorrespondenceScaling, Double)] = [
        (.principal, 1), (.standard, 0), (.symmetric, 0.5),
    ]
    for (rowScaling, rowPower) in modes {
        for (columnScaling, columnPower) in modes {
            let result = try GlifiKHMatrixPreparation.correspondenceCoordinates(
                ca, rowScaling: rowScaling, columnScaling: columnScaling)
            #expect(result.includedRows == [0, 2, 3])
            #expect(result.includedColumns == [0, 1, 2])
            #expect(result.rowMasses == ca.rowMasses)
            #expect(result.columnMasses == ca.columnMasses)
            #expect(result.singularValues == ca.singularValues)
            #expect(result.sourceMethodIdentifier == GlifiCorrespondenceResult.identifier)
            for row in result.includedRows.indices {
                for column in result.includedColumns.indices {
                    let reconstructed = ca.singularValues.indices.reduce(0.0) {
                        $0 + result.rowCoordinates[row][$1] * result.columnCoordinates[column][$1]
                            * pow(ca.singularValues[$1], 1 - rowPower - columnPower)
                    }
                    let expected =
                        matrix[result.includedRows[row]][result.includedColumns[column]]
                        / total / ca.rowMasses[row] / ca.columnMasses[column] - 1
                    #expect(abs(reconstructed - expected) < 1e-10)
                }
            }
            if rowScaling == .principal { #expect(result.rowCoordinates == ca.rowCoordinates) }
            if columnScaling == .principal {
                #expect(result.columnCoordinates == ca.columnCoordinates)
            }
            #expect(
                try JSONDecoder().decode(
                    GlifiKHCorrespondenceCoordinates.self, from: JSONEncoder().encode(result))
                    == result)
        }
    }
}

@Test("KH matrix preparation rejects malformed matrices, metadata and cumulative resource excess")
func khMatrixPreparationFailures() throws {
    for matrix in [[], [[]], [[1], [2, 3]], [[Double.nan, 1]], [[Double.infinity, 1]]]
        as [[[Double]]]
    {
        #expect(throws: GlifiFailure.self) {
            try GlifiKHMatrixPreparation.sampleZScores(matrix, axis: .rows)
        }
    }
    for exposures in [[], [-1], [.nan], [.infinity]] as [[Double]] {
        #expect(throws: GlifiFailure.self) {
            try GlifiKHMatrixPreparation.perThousand([[1]], exposures: exposures)
        }
    }
    #expect(throws: GlifiFailure.self) {
        try GlifiKHMatrixPreparation.perThousand([[-1]], exposures: [1])
    }
    #expect(throws: GlifiFailure.self) {
        try GlifiKHMatrixPreparation.sampleZScores(
            [[1, 2]], axis: .rows, limits: .init(maximumWork: 1))
    }
    #expect(throws: GlifiFailure.self) {
        try GlifiKHMatrixPreparation.sampleZScores(
            [[1, 2]], axis: .rows, limits: .init(maximumCells: 2))
    }
    let valid = GlifiKHContextCounts(level: .sentence, targetCounts: [[1]], contextCounts: [[1]])
    for levels in [
        [], [valid, valid],
        [GlifiKHContextCounts(level: .h1, alpha: .nan, targetCounts: [[1]], contextCounts: [[1]])],
        [GlifiKHContextCounts(level: .h1, targetCounts: [[1]], contextCounts: [[-1]])],
        [GlifiKHContextCounts(level: .h1, targetCounts: [[1], [1]], contextCounts: [[1]])],
    ] {
        #expect(throws: GlifiFailure.self) {
            try GlifiKHMatrixPreparation.wordContext(levels, targetIDs: ["t"], contextIDs: ["c"])
        }
    }
    for (targetIDs, contextIDs) in [([""], ["c"]), (["t", "t"], ["c"]), (["t"], [])] {
        #expect(throws: GlifiFailure.self) {
            try GlifiKHMatrixPreparation.wordContext(
                [valid], targetIDs: targetIDs, contextIDs: contextIDs)
        }
    }
    #expect(throws: GlifiFailure.self) {
        try GlifiKHMatrixPreparation.wordContext(
            khMatrixContextFixture(), targetIDs: ["a", "b", "c"], contextIDs: ["d", "e"],
            limits: .init(maximumCells: 16))
    }
    #expect(throws: GlifiFailure.self) {
        try GlifiKHMatrixPreparation.wordContext(
            khMatrixContextFixture(), targetIDs: ["a", "b", "c"], contextIDs: ["d", "e"],
            limits: .init(maximumWork: 80))
    }
    let ca = try GlifiMultivariateMethods.correspondenceAnalysis([[30, 10], [10, 30]])
    #expect(throws: GlifiFailure.self) {
        try GlifiKHMatrixPreparation.correspondenceCoordinates(
            ca, rowScaling: .standard, columnScaling: .symmetric, limits: .init(maximumCells: 3))
    }
    let encoded = try JSONEncoder().encode(ca)
    var malformed = try #require(JSONSerialization.jsonObject(with: encoded) as? [String: Any])
    malformed["singularValues"] = [0]
    let decoded = try JSONDecoder().decode(
        GlifiCorrespondenceResult.self, from: JSONSerialization.data(withJSONObject: malformed))
    #expect(throws: GlifiFailure.self) {
        try GlifiKHMatrixPreparation.correspondenceCoordinates(
            decoded, rowScaling: .standard, columnScaling: .standard)
    }
}

@Test("KH matrix preparations honor cancellation before validating or allocating outputs")
func khMatrixPreparationCancellation() async throws {
    let ca = try GlifiMultivariateMethods.correspondenceAnalysis([[30, 10], [10, 30]])
    for operation in 0..<4 {
        let task = Task {
            withUnsafeCurrentTask { $0?.cancel() }
            switch operation {
            case 0: _ = try GlifiKHMatrixPreparation.sampleZScores([[1, 2]], axis: .rows)
            case 1: _ = try GlifiKHMatrixPreparation.perThousand([[1]], exposures: [2])
            case 2:
                _ = try GlifiKHMatrixPreparation.wordContext(
                    khMatrixContextFixture(), targetIDs: ["a", "b", "c"], contextIDs: ["d", "e"])
            case 3:
                _ = try GlifiKHMatrixPreparation.correspondenceCoordinates(
                    ca, rowScaling: .standard, columnScaling: .standard)
            default: Issue.record("Unexpected operation")
            }
        }
        do {
            try await task.value
            Issue.record("A cancelled matrix preparation returned a result")
        } catch is CancellationError {
            // Cancellation remains distinguishable from domain input failures.
        }
    }
}

private func khMatrixContextFixture() -> [GlifiKHContextCounts] {
    [
        GlifiKHContextCounts(
            level: .sentence, alpha: 2,
            targetCounts: [[1, 0, 0], [5, 1, 0], [0, 1, 0]],
            contextCounts: [[1, 10], [3, 20], [5, 30]]),
        GlifiKHContextCounts(
            level: .paragraph, alpha: 0.5,
            targetCounts: [[6, 1, 0], [0, 1, 0]], contextCounts: [[4, 30], [5, 30]]),
    ]
}

private func khMatrixExpectClose(
    _ actual: [Double], _ expected: [Double], tolerance: Double = 1e-12
) {
    #expect(actual.count == expected.count)
    for (value, reference) in zip(actual, expected) {
        #expect(value.isFinite)
        #expect(abs(value - reference) <= tolerance * max(1, abs(reference)))
    }
}
